mapper.select:
	SELECT
		A.facility_id, A.group_id,B.veh_id, C.veh_no, D.route_nm, D.route_dc, A.stat_cd, A.use_tp, A.ip, A.public_ip, A.last_updt_dt
	FROM
		smartbusmngdb.sbm_facility A
		JOIN busroutedb.bms_pr_veh_lc B ON A.veh_id = B.veh_id
		JOIN busroutedb.ms_veh C ON A.veh_id = C.veh_id
		left JOIN busroutedb.matched_ms_route D ON B.route_id = D.bms_route_id
	WHERE 1=1 

	    	AND B.PROVD_DT >= CURDATE()


 	      	AND A.group_id = #{userGroupId}


	      	AND B.ROUTE_ID = #{selRouteId}



	      	AND B.ROUTE_VER = #{selRouteVer}



	     	AND B.VEH_ID = #{selVehId}



	      	AND A.STAT_CD = #{selState}



			AND A.USE_TP = #{useTp}

	  ORDER BY (A.LAST_UPDT_DT IS NULL), A.LAST_UPDT_DT DESC

SELECT *
FROM smartbusmngdb.sbm_facility
WHERE facility_id = #{facilityId}

		AND group_id = #{userGroupId}

SELECT DISTINCT manufacturer FROM smartbusmngdb.sbm_product_info
group_id = #{userGroupId}
ORDER BY manufacturer

SELECT model_id AS modelId, model_nm AS modelNm
FROM smartbusmngdb.sbm_product_info

	manufacturer = #{manufacturer}

		AND group_id = #{groupId}


ORDER BY model_nm

SELECT A.VEH_ID, B.VEH_NO, A.ROUTE_ID, A.ROUTE_VER, C.ROUTE_NM, C.ROUTE_DC
FROM busroutedb.BMS_PR_VEH_LC A, busroutedb.MS_VEH B, busroutedb.matched_ms_route C
WHERE A.PROVD_DT >= CURDATE()
	AND A.group_id = #{userGroupId}
	AND A.group_id = b.group_id
	AND A.VEH_ID = B.VEH_ID

		AND A.ROUTE_ID = #{selRouteId}
		AND C.ROUTE_ID = #{selRouteId}


		AND A.ROUTE_VER = #{selRouteVer}
		AND C.ROUTE_VER = #{selRouteVer}

ORDER BY A.VEH_NO

SELECT COUNT(*)
FROM smartbusmngdb.sbm_facility
WHERE group_id = #{groupId}
  AND model_id = #{modelId}

